@startuml

class Student {
  + studentId : string
  + dateOfBirth : date
  + city : string
  + region : string
}

class Professor {
  + name : string
  + dateOfBirth : date
  + city : string
}

class Faculty {
  + name : string
  + type : string
}

class Course {
  + code : string
  + lectureHours : int
}

class Exam {
  + grade : int
}

class Enrollment {
  + yearOfEnrollment : int
}

Student "1" -- "1" Enrollment : is_enrolled_in
Faculty "1" -- "1..*" Enrollment : contains
Student "1" -- "*" Exam : passes
Course "1" -- "*" Exam : is_subject_of
Professor "1" -- "*" Course : teaches
Faculty "1" -- "*" Course : belongs_to

@enduml

